#include <utility>
std::pair<double,double> quotes(double mid, double halfSpread,
                               long long q, double k){
    double r = mid - k * (double)q;   // reservation price, skewed by inventory
    return { r - halfSpread, r + halfSpread }; // {bid, ask}
}

def quotes(mid, half_spread, q, k):
    r = mid - k * q          # reservation price, skewed by inventory
    return (r - half_spread, r + half_spread)  # (bid, ask)
